    check(!ExperimentalSimulation::current().active,"normal game has no experimental tuning");const auto ordinary=simulateTuning();{ExperimentalSimulation::Scoped neutral(1,1,1);check(simulateTuning()==ordinary,"neutral experimental coefficients preserve exact normal-engine output");{ExperimentalSimulation::Scoped lowered(.5,1,1);check(simulateTuning()[0]<ordinary[0],"experimental coefficient changes actual takeoff distance contribution");}check(ExperimentalSimulation::current().takeoff==1,"nested experimental coefficient scope restores its parent");bool untouched=false;std::thread thread([&]{untouched=!ExperimentalSimulation::current().active;});thread.join();check(untouched,"experimental coefficients never leak into other game threads");}check(!ExperimentalSimulation::current().active,"leaving playground restores ordinary engine path");
