    const auto replay=Playground::replay(config,1,2);check(replay==Playground::replay(config,1,2) && replay["standings"].toArray().size()==12 && replay["jumps"].toArray().size()>=18,"competition replay is deterministic and includes every athlete and jump");const auto sample=parallel["variants"].toArray()[1].toObject()["samples"].toArray()[2].toObject();check(replay["gate"]==sample["gate"] && replay["standings"].toArray()[5].toObject()["place"]==sample["place"],"replayed competition matches retained focus sample");
