    auto tied=deterministic;auto tieParameters=tied["parameters"].toObject();tieParameters["field.spread"]=0;tieParameters["rules.judges"]=0;tied["parameters"]=tieParameters;tied["rounds"]=QJsonArray{12,6};check(Playground::replay(tied,0,777%24)==Playground::replay(tied,0,777%24),"seeded result identities preserve exact start order when scores tie");
