    auto disqualified=team;disqualified["focus"]=10;auto dsqValues=disqualified["parameters"].toObject();dsqValues["engine.dsq"]=1;dsqValues["rules.dsq"]=1;disqualified["parameters"]=dsqValues;const auto teamDsq=Playground::run(disqualified,std::make_shared<Playground::Control>());const auto member=teamDsq["variants"].toArray()[0].toObject()["focus"].toObject();check(member["starts"].toInt()==2 && member["jumps"].toInt()==0 && member["podiums"].toInt()==0 && member["teamDsq"].toInt()==2 && teamDsq["fieldSize"].toInt()==10,"team DSQ retains team participation for skipped squad members without inventing jumps or podiums");
    auto manual=knockout;auto manualRules=CompetitionRules::getFromJson(manual["rulesData"].toObject());manualRules.getRoundsReference()[0].setKoGroupsSelectionType(CompetitionRules::Manual);manual["rulesData"]=CompetitionRules::getJsonObject(manualRules);check(Playground::replay(manual,0,0)==Playground::replay(manual,0,0),"manual KO presets use repeatable automatic groups in batch mode");
    auto uncompensated=config;auto p=uncompensated["parameters"].toObject();p["wind.mean"]=2;p.remove("rules.windCompensation");uncompensated["parameters"]=p;rules.setCompetitionType(CompetitionRules::Individual);rules.setRounds({RoundInfo(12,true)});rules.setHasWindCompensations(false);uncompensated["rulesData"]=CompetitionRules::getJsonObject(rules);const auto noComp=Playground::replay(uncompensated,0,0);for(const auto &jump:noComp["jumps"].toArray())check(jump.toObject()["compensation"].toDouble()==0,"imported rules preserve disabled wind compensation when not overridden");
    Hill custom("Custom","POL",120,134,4.2,75,8,12,4);auto scoring=config;scoring["hill"]=QJsonObject{{"name","Custom"},{"k",120},{"hs",134},{"source",Hill::getJsonObject(custom)}};const auto customReplay=Playground::replay(scoring,0,0);for(const auto &entry:customReplay["jumps"].toArray()){const auto jump=entry.toObject();if(!jump["dsq"].toBool()){const double expected=qMax(0.,75+(jump["distance"].toDouble()-120)*4.2+jump["judges"].toDouble()+jump["compensation"].toDouble());check(std::abs(jump["points"].toDouble()-std::round(expected*10)/10)<.11,"imported hills retain manually configured points per metre and K-point score");}}
    auto sourceConfig=config;sourceConfig["competitions"]=1;QJsonArray sourceRoster;for(int i=0;i<12;++i){Jumper source("Source",QString::number(i),i%2?"POL":"NOR",JumperSkills(0,73,65,JumperSkills::HStyle,56,12));sourceRoster.append(Jumper::getJsonObject(source));}sourceConfig["roster"]=sourceRoster;sourceConfig["parameters"]=QJsonObject();const auto preserved=Playground::run(sourceConfig,std::make_shared<Playground::Control>());const auto effective=preserved["variants"].toArray()[0].toObject()["parameters"].toObject();check(effective["athlete.form"].toInt()==56 && effective["athlete.flightStyle"].toInt()==JumperSkills::HStyle && effective["athlete.takeoff"].toInt()==73,"imported focus attributes are preserved when no explicit experimental override exists");
